-- 070 Andorra Sports Tribe: squash, football pitch, boxing and spin studios; squash and table tennis sports.
SELECT v.name, v.emoji, v.cat, 4, 4, true FROM (VALUES ('Squash', '🎾', 'racket'), ('Table Tennis', '🏓', 'racket')) AS v(name, emoji, cat)
WHERE NOT EXISTS (SELECT 1 FROM sports s WHERE lower(s.name) = lower(v.name));

ON CONFLICT (id) DO NOTHING;

UPDATE facilities SET image_url = 'https://beast-tribe.vercel.app/places/andorra/padel-racket.jpg' WHERE id = 'a1d0aa00-0000-4000-8000-000000000012';
